// This file wraps the generated OpenNext Worker. It is intentionally excluded
// from Next.js type-checking because .open-next/worker.js only exists after the
// application build.
// The generated module may or may not exist when TypeScript runs, so an
// expectation directive would itself fail after a local OpenNext build.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore -- Generated by `opennextjs-cloudflare build`.
import openNextWorker from './.open-next/worker.js';
import { documentContentSecurityPolicy } from './src/lib/contentSecurityPolicy';
import { guessLanguage } from './src/lib/languageGuess';
import { legacyHostRedirect } from './src/lib/legacyHost';
import { movedMapRedirect } from './src/lib/mapAddress';
import { pageRequest } from './src/lib/pageRequest';
import { proxyScooterSnapshot } from './src/lib/scooterProxy';

function secureDocumentResponse(request: Request, response: Response): Response {
  if (!response.headers.get('Content-Type')?.toLowerCase().startsWith('text/html')) {
    return response;
  }

  const nonce = btoa(crypto.randomUUID());
  const headers = new Headers(response.headers);
  headers.delete('Content-Length');
  headers.set(
    'Content-Security-Policy',
    documentContentSecurityPolicy({
      nonce,
      development: false,
      upgradeInsecureRequests: new URL(request.url).protocol === 'https:',
    }),
  );
  const documentResponse = new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
  const nonceHandler = {
    element(element: Element) {
      element.setAttribute('nonce', nonce);
    },
  };

  const guessed = guessedLanguage(request);
  return new HTMLRewriter()
    .on('script', nonceHandler)
    .on('style', nonceHandler)
    // Next's hints to fetch a script early: under 'strict-dynamic' a hint without
    // the nonce is refused, though the script it names then loads by its tag.
    .on('link[rel="preload"][as="script"]', nonceHandler)
    .on('link[rel="modulepreload"]', nonceHandler)
    .on('[data-guess-page]', guessed.languages)
    .on('[data-guess-seat]', guessed.seat)
    .transform(documentResponse);
}

/**
 * The second seat of the languages in the bar of the site, made again for
 * this visitor: the page was built with the guess for someone we know nothing
 * about (src/app/(site)/chrome.tsx). The languages come first in the page and
 * say which the guess can be; then the seat of the guess is shown and the
 * others hidden. Only attributes change, so the page still hydrates as React
 * rendered it.
 */
function guessedLanguage(request: Request) {
  let guess: string | undefined;
  const place = request.cf as IncomingRequestCfProperties | undefined;

  return {
    languages: {
      element(element: Element) {
        const page = element.getAttribute('data-guess-page');
        if (!page) return;
        guess = guessLanguage({
          page,
          available: element.getAttribute('data-guess-from')?.split(' ') ?? [],
          acceptLanguage: request.headers.get('Accept-Language'),
          country: place?.country,
          region: place?.regionCode,
        });
      },
    },
    seat: {
      element(element: Element) {
        if (element.getAttribute('data-guess-seat') === guess) element.removeAttribute('hidden');
        else element.setAttribute('hidden', '');
      },
    },
  };
}

const scootRadarWorker = {
  async fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext) {
    const redirect = legacyHostRedirect(request) ?? movedMapRedirect(request);
    if (redirect) {
      return redirect;
    }

    const { pathname } = new URL(request.url);
    if ((pathname === '/api/scooters' || pathname === '/api/zones') && env.SCOOTER_SNAPSHOT_API_URL) {
      return proxyScooterSnapshot(request, env, { cache: caches.default, waitUntil: promise => ctx.waitUntil(promise) });
    }

    const response = await openNextWorker.fetch(pageRequest(request), env, ctx);
    return secureDocumentResponse(request, response);
  },
};

export default scootRadarWorker;
